#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int factor(char **p) {
    if (**p == '(') { (*p)++; int v = expr(p); if (**p == ')') (*p)++; return v; }
    return strtol(*p, p, 10);
}

int term(char **p) {
    int v = factor(p);
    while (**p == '*' || **p == '/') {
        char op = *(*p)++;
        int r = factor(p);
        v = (op == '*') ? v * r : v / r;
    }
    return v;
}

int expr(char **p) {
    int v = term(p);
    while (**p == '+' || **p == '-') {
        char op = *(*p)++;
        int r = term(p);
        v = (op == '+') ? v + r : v - r;
    }
    return v;
}

int main() {
    char input[] = "3+4*2";
    char *p = input;
    printf("Result: %d\n", expr(&p));
    return 0;
}
